"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[1991],{25727:e=>{e.exports=JSON.parse('{"functions":[{"name":"chunk","desc":"Generates one chunk from its coordinates alone.\\n\\nThe pass order is load-bearing:\\n\\n1. `rooms.place` stamps footprints and marks their cells `captured`.\\n2. `maze.carve` carves corridors, routing around anything captured.\\n3. `maze.openDoors` opens the chunk-border doorways.\\n4. `features.place` classifies the finished corridors and drops props in.\\n5. `grid.materialiseWalls` freezes the edge grids onto the cell records.\\n\\nEverything is derived from the chunk seed, so the same coordinates always\\nproduce the same chunk regardless of what order chunks load in.","params":[{"name":"worldSeed","desc":"Seed every chunk derives from.","lua_type":"number"},{"name":"chunkX","desc":"Chunk column.","lua_type":"number"},{"name":"chunkY","desc":"Chunk row.","lua_type":"number"}],"returns":[{"desc":"The finished maze, walls materialised.","lua_type":"Maze"},{"desc":"Rooms and features to build.","lua_type":"{ Placement }"},{"desc":"Merged wall runs to build.","lua_type":"{ mesher.Run }"}],"function_type":"static","source":{"line":48,"path":"src/main/server/helpers/generate.luau"}},{"name":"stripOwnedBorders","desc":"Drops the wall runs that belong to the neighbouring chunk.\\n\\nEvery chunk meshes all four of its borders, so each shared border would be\\nbuilt twice \u2014 once by each side. By convention a chunk owns its far borders\\nand the neighbour owns the near ones, so the runs on `x == 0` and `y == 0`\\nare discarded here.","params":[{"name":"runs","desc":"Mutated in place.","lua_type":"{ mesher.Run }"}],"returns":[{"desc":"The same table, foreign borders removed.","lua_type":"{ mesher.Run }"}],"function_type":"static","source":{"line":84,"path":"src/main/server/helpers/generate.luau"}}],"properties":[],"types":[],"name":"generate","desc":"Chunk generation. Runs the four passes that turn a chunk coordinate into a\\nfinished maze, in the one order they work in.","tags":["server-helper"],"realm":["Server"],"source":{"line":11,"path":"src/main/server/helpers/generate.luau"}}')}}]);